# Mirror-first Android SDK preparation for Iran-network constrained builds.
# This file is a small helper and is intended to be called by the main environment script.
$AndroidMirrorRoots=@('https://mirrors.aliyun.com/android/repository/','https://mirrors.cloud.tencent.com/AndroidSDK/','https://mirrors.huaweicloud.com/repository/toolkit/android/repository/')
$AndroidCmdlineZip='commandlinetools-win-15859902_latest.zip'
function Get-AndroidMirrors{if($env:KHATYAR_ANDROID_MIRROR_URL){return @($env:KHATYAR_ANDROID_MIRROR_URL.TrimEnd('/')+'/')+$AndroidMirrorRoots|Select-Object -Unique};return $AndroidMirrorRoots}
function Set-AndroidMirror([string]$Mirror){$url=$Mirror.TrimEnd('/')+'/';$env:SDK_TEST_BASE_URL=$url;$u=Join-Path $env:USERPROFILE '.android';New-Item -ItemType Directory -Force -Path $u|Out-Null;Set-Content -LiteralPath (Join-Path $u 'repositories.cfg') -Encoding ASCII -Value @('### KhatYar non-Google Android SDK mirror','repo-type=legacy',('url='+$url))}
function Download-AndroidCli([string]$Destination){$last=$null;foreach($mirror in Get-AndroidMirrors){try{Write-Host "[environment] Android mirror: $mirror" -ForegroundColor DarkGray;Invoke-WebRequest -Uri ($mirror+$AndroidCmdlineZip) -OutFile $Destination -UseBasicParsing -TimeoutSec 180;if((Get-Item $Destination).Length -lt 10MB){throw 'Downloaded archive is unexpectedly small.'};return}catch{$last=$_.Exception.Message;Remove-Item $Destination -Force -ErrorAction SilentlyContinue;Write-Warning "Android mirror failed: $last"}};throw "No reachable non-Google Android mirror can provide $AndroidCmdlineZip. Configure KHATYAR_ANDROID_MIRROR_URL."}
